def parenteses_balanceados(s):
    pares = {"}": "{", ")": "(", "]": "["}
    pilha = []
    for caractere in s:
        if caractere in "([{":
            pilha.append(caractere)
        elif caractere in ")]}":
            if not pilha or pilha.pop() != pares[caractere]:
                return False
    return not pilha

